{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Clobazam, a 1,5-benzodiazepine with a chlorophenyl substituent, has 90% oral bioavailability in healthy volunteers; the close benzodiazepine scaffold and high transfer score strongly support high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Trazodone, a CNS-active chlorophenyl heterocycle, showed absolute oral bioavailability of 82% in fasted men, supporting high F for this similarly lipophilic CNS-oriented molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Meclofenamate, a chlorophenyl-containing aromatic drug, has human bioavailability above 85%, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Oxaprozin has nearly complete oral absorption and high systemic availability in humans, providing additional high-bioavailability evidence from a small lipophilic molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Encorafenib, an orally administered small-molecule drug, has 85% human bioavailability, supporting the pattern that moderate-MW lipophilic drugs with low HBD can achieve high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Compound 26 was predicted to have 23% human oral bioavailability, still above the 20% threshold; this is weak supportive evidence because it is a prediction rather than a direct measurement.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a benzodiazepine N-oxide (chlordiazepoxide-like) with favorable physicochemical properties. High-transfer experimental evidence from clobazam (90% F), trazodone (63-91% F), and other orally bioavailable drugs strongly supports F >= 20%. Low-F analogues such as loperamide and batimastat have negligible transfer scores and are not applicable. Therefore the prediction is high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself was provided.",
    "The most structurally similar high-F analogue, clobazam, is a 1,5-benzodiazepine rather than the 1,4-benzodiazepine N-oxide scaffold of the query.",
    "One supportive record (compound 26) is based on allometric scaling prediction rather than experimental human data."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

